import{X as e,Y as t,ct as n,t as r}from"./chunks/framework.CaFWb3SA.js";var i=JSON.parse(`{"title":"角色的定义、注册、使用与注销","description":"","frontmatter":{},"headers":[],"relativePath":"guide/advanced/Character.md","filePath":"guide/advanced/Character.md"}`),a={name:`guide/advanced/Character.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="角色的定义、注册、使用与注销" tabindex="-1">角色的定义、注册、使用与注销 <a class="header-anchor" href="#角色的定义、注册、使用与注销" aria-label="Permalink to “角色的定义、注册、使用与注销”">​</a></h1><h2 id="前言与确认" tabindex="-1">前言与确认 <a class="header-anchor" href="#前言与确认" aria-label="Permalink to “前言与确认”">​</a></h2><p>Era 系列游戏的核心是“角色”。无论是养成、冒险还是经营，玩家操作的对象、数值的载体，最终都是一个个角色。这一节，我们正式和角色打交道。</p><div class="warning custom-block"><p class="custom-block-title">教程依赖</p><p>本教程假设您已学习过<a href="./../Quick_Start.html">快速开始</a>、<a href="./../tutorials/">入门教程</a>（尤其是<a href="./../tutorials/Function.html">函数的定义与用法</a>）。若您尚未学习过，我们强烈推荐您首先学习相应教程。</p></div><p>先确认一下我们现有的工程文件夹结构：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span>root/</span></span>
<span class="line"><span> ├─ emuera.config</span></span>
<span class="line"><span> ├─ Emuera1824.exe</span></span>
<span class="line"><span> ├─ CSV/</span></span>
<span class="line"><span> └─ ERB/</span></span>
<span class="line"><span>     └─ System.erb</span></span></code></pre></div><h2 id="用-csv-定义角色" tabindex="-1">用 CSV 定义角色 <a class="header-anchor" href="#用-csv-定义角色" aria-label="Permalink to “用 CSV 定义角色”">​</a></h2><p>角色不是凭空写出来的，而是先在 <code>CSV/</code> 里定义好，再由脚本“注册”进游戏。</p><p>在 <code>CSV/</code> 中新建一个 <code>Chara01.csv</code>，内容如下：</p><div class="language-csv"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">csv</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#E6E6E6;">番号,1</span></span>
<span class="line"><span style="color:#E6E6E6;">名前,小明</span></span>
<span class="line"><span style="color:#E6E6E6;">呼び名,小明</span></span>
<span class="line"><span style="color:#E6E6E6;">基礎,0,2000</span></span>
<span class="line"><span style="color:#E6E6E6;">基礎,1,1000</span></span>
<span class="line"><span style="color:#E6E6E6;">能力,0,10</span></span></code></pre></div><p>逐行看：</p><table tabindex="0"><thead><tr><th>行</th><th>含义</th></tr></thead><tbody><tr><td><code>番号,1</code></td><td>这个角色的编号是 1</td></tr><tr><td><code>名前,小明</code></td><td>名字叫“小明”（<code>NAME</code>）</td></tr><tr><td><code>呼び名,小明</code></td><td>称呼叫“小明”（<code>CALLNAME</code>）</td></tr><tr><td><code>基礎,0,2000</code></td><td>基础属性 0 号（体力）的初始值为 2000</td></tr><tr><td><code>基礎,1,1000</code></td><td>基础属性 1 号（精力）的初始值为 1000</td></tr><tr><td><code>能力,0,10</code></td><td>能力 0 号的初始值为 10</td></tr></tbody></table><p>角色在 CSV 里可以定义名字、基础数据、能力、素质、经验、相性等一大堆属性。现在先了解这些，用不到的先放着。</p><h2 id="注册角色-addchara" tabindex="-1">注册角色：ADDCHARA <a class="header-anchor" href="#注册角色-addchara" aria-label="Permalink to “注册角色：ADDCHARA”">​</a></h2><p>定义好 CSV 之后，脚本里用 <code>ADDCHARA</code> 把角色“请”进游戏：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">EVENTFIRST</span></span>
<span class="line"><span style="color:#569CD6;">  ADDCHARA</span><span style="color:#B5CEA8;"> 1</span></span>
<span class="line"><span style="color:#569CD6;">  QUIT</span></span></code></pre></div><p><code>ADDCHARA 1</code> 里的 <code>1</code> 是 CSV 里的<strong>角色编号</strong>（也就是 <code>番号,1</code> 的那个 1）。执行后，游戏里就多了一个角色。</p><h2 id="认识三个-身份" tabindex="-1">认识三个“身份” <a class="header-anchor" href="#认识三个-身份" aria-label="Permalink to “认识三个“身份””">​</a></h2><p>Emuera 用几个内置变量来指代角色，初学者最容易被它们绕晕，这里一次说清：</p><table tabindex="0"><thead><tr><th>变量</th><th>含义</th></tr></thead><tbody><tr><td><code>MASTER</code></td><td>主角（玩家），通常是编号 0</td></tr><tr><td><code>TARGET</code></td><td>当前被操作的对象</td></tr><tr><td><code>CHARANUM</code></td><td>当前游戏里一共有多少个角色</td></tr><tr><td><code>NO:角色</code></td><td>某个角色的 CSV 编号</td></tr></tbody></table><p>此外，每个角色都有一个<strong>登录编号</strong>（0、1、2……），用来在脚本里定位它。角色变量（如 <code>NAME</code>、<code>BASE</code>）不写编号时，默认指 <code>TARGET</code>。</p><h2 id="使用角色" tabindex="-1">使用角色 <a class="header-anchor" href="#使用角色" aria-label="Permalink to “使用角色”">​</a></h2><h3 id="读取属性" tabindex="-1">读取属性 <a class="header-anchor" href="#读取属性" aria-label="Permalink to “读取属性”">​</a></h3><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">EVENTFIRST</span></span>
<span class="line"><span style="color:#569CD6;">  ADDCHARA</span><span style="color:#B5CEA8;"> 1</span></span>
<span class="line"><span style="color:#569CD6;">  #</span><span style="color:#C586C0;">Dim</span><span style="color:#9CDCFE;"> Index</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 0</span></span>
<span class="line"><span style="color:#9CDCFE;">  Index</span><span style="color:#D4D4D4;"> =</span><span style="color:#9CDCFE;"> CHARANUM</span><span style="color:#D4D4D4;"> -</span><span style="color:#B5CEA8;"> 1</span></span>
<span class="line"></span>
<span class="line"><span style="color:#569CD6;">  PRINTL</span><span style="color:#9CDCFE;"> 最后一个角色的名字是：</span></span>
<span class="line"><span style="color:#569CD6;">  PRINTS</span><span style="color:#9CDCFE;"> NAME</span><span style="color:#D4D4D4;">:</span><span style="color:#9CDCFE;">Index</span></span>
<span class="line"><span style="color:#569CD6;">  PRINTL</span></span>
<span class="line"><span style="color:#569CD6;">  PRINTL</span><span style="color:#9CDCFE;"> 它的体力是：</span></span>
<span class="line"><span style="color:#569CD6;">  PRINTV</span><span style="color:#9CDCFE;"> BASE</span><span style="color:#D4D4D4;">:</span><span style="color:#9CDCFE;">Index</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span></span>
<span class="line"><span style="color:#569CD6;">  PRINTL</span></span>
<span class="line"><span style="color:#569CD6;">  QUIT</span></span></code></pre></div><p><code>NAME:Index</code> 是“登录编号为 Index 的角色”的名字；<code>BASE:Index:0</code> 是它的 0 号基础属性（体力）。数组下标可以从 0 开始，所以最后一个角色的下标是 <code>CHARANUM - 1</code>。</p><h3 id="修改属性" tabindex="-1">修改属性 <a class="header-anchor" href="#修改属性" aria-label="Permalink to “修改属性”">​</a></h3><p>角色变量也能像普通变量一样直接赋值：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">EVENTFIRST</span></span>
<span class="line"><span style="color:#569CD6;">  ADDCHARA</span><span style="color:#B5CEA8;"> 1</span></span>
<span class="line"><span style="color:#569CD6;">  #</span><span style="color:#C586C0;">Dim</span><span style="color:#9CDCFE;"> Index</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 0</span></span>
<span class="line"><span style="color:#9CDCFE;">  Index</span><span style="color:#D4D4D4;"> =</span><span style="color:#9CDCFE;"> CHARANUM</span><span style="color:#D4D4D4;"> -</span><span style="color:#B5CEA8;"> 1</span></span>
<span class="line"></span>
<span class="line"><span style="color:#9CDCFE;">  BASE</span><span style="color:#D4D4D4;">:</span><span style="color:#9CDCFE;">Index</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 2500</span></span>
<span class="line"><span style="color:#569CD6;">  PRINTL</span><span style="color:#9CDCFE;"> 体力被改成了：</span></span>
<span class="line"><span style="color:#569CD6;">  PRINTV</span><span style="color:#9CDCFE;"> BASE</span><span style="color:#D4D4D4;">:</span><span style="color:#9CDCFE;">Index</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span></span>
<span class="line"><span style="color:#569CD6;">  PRINTL</span></span>
<span class="line"><span style="color:#569CD6;">  QUIT</span></span></code></pre></div><p>习惯上，人物关系、好感之类的自定义数据会存在 <code>CFLAG</code>（角色标志）里，比如 <code>CFLAG:Index:0 = 50</code>。它就像挂在角色身上的、你自己定义的一排抽屉。</p><h2 id="注销角色-delchara" tabindex="-1">注销角色：DELCHARA <a class="header-anchor" href="#注销角色-delchara" aria-label="Permalink to “注销角色：DELCHARA”">​</a></h2><p>把角色从游戏中移除，用 <code>DELCHARA</code>：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#569CD6;">DELCHARA</span><span style="color:#B5CEA8;"> 1</span><span style="color:#6A9955;">        ; 移除登录编号为 1 的角色</span></span></code></pre></div><p>如果想清空所有角色，可以用：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#569CD6;">DELALLCHARA</span></span></code></pre></div><blockquote><p><code>DELALLCHARA</code> 会连主角一起删掉，通常配合 <code>RESETDATA</code>（重置全部数据）使用。真要用时，记得再补上必要的角色。</p></blockquote><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><ul><li>角色先在 <code>CSV/CharaXX.csv</code> 里定义，再用 <code>ADDCHARA &lt;CSV编号&gt;</code> 注册进游戏；</li><li><code>MASTER</code> 是主角，<code>TARGET</code> 是当前对象，<code>CHARANUM</code> 是角色总数；</li><li>角色变量用 <code>变量名:登录编号[:元素]</code> 访问，如 <code>NAME:0</code>、<code>BASE:0:0</code>；</li><li><code>CFLAG</code> 常用于存放自定义的关系、好感等数据；</li><li><code>DELCHARA</code> 注销单个角色，<code>DELALLCHARA</code> 清空全部。</li></ul><p>角色有了，接下来就是给游戏加上玩法循环。请进入<a href="./Experience.html">开发实战经验与技巧</a>，或者回到<a href="./../tutorials/">入门教程</a>继续打基础。</p>`,38)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};